<?php
declare(strict_types=1);
$dsn=getenv('TEST_DB_DSN')?:'mysql:host=127.0.0.1;port=3306;dbname=jomcommunicate;charset=utf8mb4';$user=getenv('TEST_DB_USER')?:'root';$pass=getenv('TEST_DB_PASS')?:'';
try{$db=new PDO($dsn,$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$required=['users','tourist_profiles','businesses','business_phrases','business_faqs','business_terms','malaysian_terms','phrase_packs','records','consent_records','translation_reports','analytics_events','business_interactions','audit_logs'];$found=$db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$missing=array_diff($required,$found);if($missing)throw new RuntimeException('Missing tables: '.implode(', ',$missing));$terms=(int)$db->query('SELECT COUNT(*) FROM malaysian_terms')->fetchColumn();if($terms<4)throw new RuntimeException('Malaysian terminology seed is incomplete.');$columns=$db->query('SHOW COLUMNS FROM users')->fetchAll(PDO::FETCH_COLUMN);foreach(['failed_login_attempts','locked_until'] as $column)if(!in_array($column,$columns,true))throw new RuntimeException('Missing lockout column: '.$column);echo "PASS: database schema and seeds\n";}catch(Throwable $e){fwrite(STDERR,'FAILED: '.$e->getMessage()."\n");exit(1);}
